data.minimal_example:
import 'package:flutter_gantt/flutter_gantt.dart';

Gantt(
  theme: GanttTheme.of(context),
  activitiesAsync: (start, end, act) async => _activities,
  holidaysAsync: (start, end, hol) async => _holidays,
  onActivityChanged: (activity, start, end) {
    if (start != null && end != null) {
      debugPrint('$activity was moved');
    }
  },
)
